// Package links resolves zortex links ("[Projects/#1 Programming/#1.4]") to
// locations in a notes folder. It ports core/link from the plugin;
// links_test.go checks it against tests/fixtures/resolve.json, generated by
// the Lua resolver.
//
// A link is "/"-separated components, resolved left to right; each narrows
// the candidates (files, then line ranges):
//
//	Projects, P        article: files declaring the alias, then files tagged with it
//	@P                 tag: files whose header has the tag
//	#1.4 - zortex      heading starting with the text, any depth
//	:Fitness           label    *Bold  highlight    -Item  list item (key or text)
//	%text              line query (case-sensitive when the query has capitals)
//	>Book              the links on lines in range whose text (or line's text)
//	                   starts with "Book"; last component only (Result.Link)
//
// Results come back in note order; the first is the canonical target.
package links

import (
	"errors"
	"net/url"
	"sort"
	"strings"

	"github.com/t-wilkinson/zortex.nvim/app/notes"
	"github.com/t-wilkinson/zortex.nvim/app/syntax"
)

// Component is one parsed link component.
type Component struct {
	Type     string // article tag heading label listitem highlight query follow
	Text     string // text without prefix (and without attributes for article/heading/label)
	Original string // as written
}

// Definition is a parsed link.
type Definition struct {
	Local      bool // "[/#Heading]": resolves in the current note
	Components []Component
}

// =============================================================================
// Grammar
// =============================================================================

// SplitLink splits a link into raw components, ignoring "/" inside
// parentheses; strips the outer brackets.
func SplitLink(def string) ([]string, bool) {
	def = syntax.Trim(def)
	if len(def) >= 2 && def[0] == '[' && def[len(def)-1] == ']' {
		def = def[1 : len(def)-1]
	}
	local := false
	if strings.HasPrefix(def, "/") {
		local = true
		def = def[1:]
	} else if strings.HasPrefix(def, "~/") {
		// the notes folder, from a note outside it: here, every note is in it
		def = def[2:]
	}
	var parts []string
	depth, start := 0, 0
	flush := func(end int) {
		if end > start {
			parts = append(parts, syntax.Trim(def[start:end]))
		}
	}
	for i := 0; i < len(def); i++ {
		switch def[i] {
		case '(':
			depth++
		case ')':
			depth--
		case '/':
			if depth == 0 {
				flush(i)
				start = i + 1
			}
		}
	}
	flush(len(def))
	return parts, local
}

// removeAttrs drops "@key (value)" (key alphanumeric), collapses whitespace
// and trims the end, like the component cleanup in parse_link_component.
func removeAttrs(s string) string {
	var b []byte
	for i := 0; i < len(s); {
		if s[i] == '@' {
			j := i + 1
			for j < len(s) && isAlnum(s[j]) {
				j++
			}
			if j > i+1 {
				k := j
				for k < len(s) && isSpace(s[k]) {
					k++
				}
				if k < len(s) && s[k] == '(' {
					if end := strings.IndexByte(s[k:], ')'); end >= 0 {
						i = k + end + 1
						continue
					}
				}
			}
		}
		b = append(b, s[i])
		i++
	}
	out := make([]byte, 0, len(b))
	for i := 0; i < len(b); {
		if isSpace(b[i]) {
			for i < len(b) && isSpace(b[i]) {
				i++
			}
			out = append(out, ' ')
			continue
		}
		out = append(out, b[i])
		i++
	}
	end := len(out)
	for end > 0 && isSpace(out[end-1]) {
		end--
	}
	return string(out[:end])
}

func isSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\v' || b == '\f' || b == '\r'
}

func isAlnum(b byte) bool {
	return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// ParseComponent types one component.
func ParseComponent(c string) Component {
	switch c[0] {
	case '@':
		return Component{Type: "tag", Text: c[1:], Original: c}
	case '#':
		text := c[1:]
		if strings.HasPrefix(text, " ") {
			text = text[1:]
		}
		return Component{Type: "heading", Text: removeAttrs(text), Original: c}
	case ':':
		return Component{Type: "label", Text: removeAttrs(c[1:]), Original: c}
	case '-':
		return Component{Type: "listitem", Text: c[1:], Original: c}
	case '*':
		return Component{Type: "highlight", Text: c[1:], Original: c}
	case '%':
		return Component{Type: "query", Text: c[1:], Original: c}
	case '>':
		return Component{Type: "follow", Text: syntax.Trim(c[1:]), Original: c}
	}
	return Component{Type: "article", Text: removeAttrs(c), Original: c}
}

// Parse parses a link definition ("[A/#B]", "A/#B", "[/#Local]").
func Parse(def string) Definition {
	parts, local := SplitLink(def)
	d := Definition{Local: local}
	for _, p := range parts {
		if p != "" {
			d.Components = append(d.Components, ParseComponent(p))
		}
	}
	return d
}

// =============================================================================
// Line matching (search_lines)
// =============================================================================

// Match is a matching line (1-based line and column); Link is the link a
// follow component matched.
type Match struct {
	Lnum, Col int
	Link      *syntax.Span
}

// LinkText is line from byte from on, links without their brackets:
// markdown links and links written with their text by that text ("[The
// Rust Book](https://…) @rust" -> "The Rust Book @rust", "[the plan](P/#1.4)"
// -> "the plan"), other links by what is inside ("To [this link]" -> "To
// this link"). List items match a listitem component by this text, as
// Neovim's link.link_text.
func LinkText(line string, from int) string {
	if !strings.Contains(line[from:], "[") {
		return line[from:]
	}
	var spans []syntax.Span
	syntax.Walk(syntax.Inline(line, 0, len(line)), func(sp *syntax.Span) {
		if (sp.Type == "markdown" || sp.Type == "link") && sp.S >= from {
			spans = append(spans, *sp)
		}
	})
	sort.SliceStable(spans, func(i, j int) bool { return spans[i].S < spans[j].S })
	var b strings.Builder
	pos := from
	for _, sp := range spans {
		if sp.S >= pos {
			b.WriteString(line[pos:sp.S])
			if sp.Text != "" || sp.Type == "markdown" {
				b.WriteString(sp.Text)
			} else {
				b.WriteString(sp.Definition)
			}
			pos = sp.E
		}
	}
	b.WriteString(line[pos:])
	return b.String()
}

// followable: spans a follow component can follow.
var followable = map[string]bool{"link": true, "live_link": true, "markdown": true, "url": true, "filepath": true}

// FollowTarget is a link a follow component can match.
type FollowTarget struct {
	Span syntax.Span
	Text string // markdown text, link definition, URL or path
}

// FollowTargets lists the links on a line a follow component can match.
func FollowTargets(line string) []FollowTarget {
	var out []FollowTarget
	syntax.Walk(syntax.Inline(line, 0, len(line)), func(sp *syntax.Span) {
		if !followable[sp.Type] {
			return
		}
		out = append(out, FollowTarget{Span: *sp, Text: SpanText(sp)})
	})
	return out
}

// SpanText is the text a follow component matches for a link span: a
// markdown link's text, a zortex link's text ([text](P/#1.4)) or definition,
// a URL or a path.
func SpanText(sp *syntax.Span) string {
	switch sp.Type {
	case "markdown":
		return sp.Text
	case "link", "live_link":
		if sp.Text != "" {
			return sp.Text
		}
		return sp.Definition
	case "url":
		return sp.URL
	case "filepath":
		return sp.Path
	}
	return ""
}

// followLineText is a line's text for follow matching: a list item's text,
// or the trimmed line, without attributes.
func followLineText(line string) string {
	if it := syntax.ItemOf(line); it != nil {
		line = line[it.ContentCol:]
	}
	return syntax.Trim(syntax.StripAttributes(line))
}

func headingMatch(line, text string) bool {
	hashes := 0
	for hashes < len(line) && line[hashes] == '#' {
		hashes++
	}
	for k := hashes; k >= 1; k-- {
		ws := 0
		for k+ws < len(line) && isSpace(line[k+ws]) {
			ws++
		}
		for w := ws; w >= 0; w-- {
			if strings.HasPrefix(line[k+w:], text) {
				return true
			}
		}
	}
	return false
}

func highlightCol(line, text string) int {
	for p := 0; p < len(line); p++ {
		if line[p] != '*' {
			continue
		}
		for s := 3; s >= 1; s-- {
			if p+s > len(line) || strings.Count(line[p:p+s], "*") != s {
				continue
			}
			rest := line[p+s:]
			if strings.HasPrefix(rest, text) {
				after := strings.TrimPrefix(rest[len(text):], ":") // bold heading "**text:**"
				if strings.HasPrefix(after, "*") {
					return p + 1
				}
			}
		}
	}
	return 0
}

// listItemMatch: want is the component lower-cased; idAttr "@id(aB3x9)" (or
// "") matches a task's @id exactly, so a link survives renames.
func listItemMatch(line, want, idAttr string) (int, bool) {
	if syntax.Trim(line) == "" {
		return 0, false
	}
	it := syntax.ItemOf(line)
	if it == nil {
		return 0, false
	}
	key := syntax.Lower(it.Key)
	body := syntax.Lower(syntax.StripAttributes(LinkText(line, it.ContentCol)))
	if (it.Key != "" && key == want) || strings.HasPrefix(body, want) || (it.Key != "" && strings.HasPrefix(key, want)) ||
		(idAttr != "" && strings.Contains(line, idAttr)) {
		return it.MarkerCol + 1, true
	}
	return 0, false
}

// idAttrOf: "@id(text)" when text could be a task id (word characters and
// dashes), else "".
func idAttrOf(text string) string {
	if text == "" {
		return ""
	}
	for i := 0; i < len(text); i++ {
		c := text[i]
		if !(isAlnum(c) || c == '_' || c == '-') {
			return ""
		}
	}
	return "@id(" + text + ")"
}

func hasUpper(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			return true
		}
	}
	return false
}

// SearchLines finds the lines in [start, end] (1-based, inclusive; 0 = whole
// note) matching a component. Matching ignores ASCII case, except queries
// whose text has a capital.
func SearchLines(lines []string, c Component, start, end int) []Match {
	if start <= 0 {
		start = 1
	}
	if end <= 0 || end > len(lines) {
		end = len(lines)
	}
	var out []Match
	if c.Type == "listitem" {
		want := syntax.Lower(syntax.Trim(c.Text))
		idAttr := idAttrOf(syntax.Trim(c.Text))
		for lnum := start; lnum <= end; lnum++ {
			if col, ok := listItemMatch(lines[lnum-1], want, idAttr); ok {
				out = append(out, Match{Lnum: lnum, Col: col})
			}
		}
		return out
	}
	if c.Type == "follow" {
		// every link whose own text, or whose line's text, starts with the
		// component text; "" matches every link
		want := syntax.Lower(c.Text)
		starts := func(s string) bool { return strings.HasPrefix(syntax.Lower(s), want) }
		for lnum := start; lnum <= end; lnum++ {
			line := lines[lnum-1]
			if !strings.ContainsAny(line, "[/:") {
				continue
			}
			targets := FollowTargets(line)
			if len(targets) == 0 {
				continue
			}
			whole := starts(followLineText(line))
			for i := range targets {
				if whole || starts(targets[i].Text) {
					out = append(out, Match{Lnum: lnum, Col: targets[i].Span.S + 1, Link: &targets[i].Span})
				}
			}
		}
		return out
	}
	if c.Type == "article" {
		return nil // only selects files (global links); nothing to search in a note
	}
	caseSensitive := c.Type == "query" && hasUpper(c.Text)
	norm := func(s string) string {
		if caseSensitive {
			return s
		}
		return syntax.Lower(s)
	}
	text := norm(c.Text)
	for lnum := start; lnum <= end; lnum++ {
		line := norm(lines[lnum-1])
		col := 0
		switch c.Type {
		case "tag":
			if line == "@"+text {
				col = 1
			}
		case "heading":
			if headingMatch(line, text) {
				col = 1
			}
		case "label":
			// "Label:", or a longer label written "*A longer label:*"
			l := strings.TrimPrefix(line, "*")
			if strings.HasPrefix(l, text) && strings.IndexByte(l[len(text):], ':') >= 0 {
				col = 1
			}
		case "highlight":
			col = highlightCol(line, text)
		case "query":
			if i := strings.Index(line, text); i >= 0 {
				col = i + 1
			}
		}
		if col > 0 {
			out = append(out, Match{Lnum: lnum, Col: col})
		}
	}
	return out
}

// SectionEnd is the range a match narrows to: the section starting at the
// matched line (a single line for list items, queries, tags and plain
// highlights).
func SectionEnd(doc *notes.Document, lnum int, c Component) int {
	switch c.Type {
	case "listitem", "query", "tag", "follow":
		return lnum
	}
	node := doc.NodeStartingAt(lnum)
	if c.Type == "highlight" && (node == nil || node.Type != "bold_heading") {
		return lnum
	}
	if node != nil {
		return node.End
	}
	if c.Type == "article" {
		return len(doc.Lines)
	}
	return lnum
}

// =============================================================================
// Resolution
// =============================================================================

// Result is a location a link resolves to.
type Result struct {
	Doc       *notes.Document
	Lnum, Col int
	Component Component
	Link      *syntax.Span // follow components: the link to follow
	Whole     bool         // a whole note (article and tag components)
	End       int          // line searches: last line of the range the result covers
}

// Options for Resolve.
type Options struct {
	From            *notes.Document // the current note, for local links
	Lnum            int             // the line the link is written on (parent-relative links)
	IncludeArchived *bool           // nil: only when a component is @Archive
}

// NoParentLink: a parent-relative link with no link on a parent line.
const NoParentLink = "No link on a parent line for ./"

// OSPath reports a link to a file elsewhere on the computer, outside the
// notes: "~/…" or an absolute path whose first part isn't a section of the
// note ("/home/me/a.pdf", not "/#Heading" or "/-Item"). Such links are never
// broken; a "~/" link that finds a note still goes there. As Neovim's
// link.os_path (without expanding "~": the server's home isn't yours).
func OSPath(def string) bool {
	def = strings.TrimSpace(def)
	if strings.HasPrefix(def, "[") && strings.HasSuffix(def, "]") {
		def = def[1 : len(def)-1]
	}
	if SitePath(def) != "" {
		return false // the web app's own address of a file in the notes
	}
	if strings.HasPrefix(def, "~/") && len(def) > 2 {
		return true
	}
	return len(def) > 1 && def[0] == '/' && !strings.ContainsRune("#:*-%>@/ \t", rune(def[1]))
}

// SitePath: the notes-folder path a web app address names, "/raw/z/scan.pdf",
// "/f/z/books/" or "/n/projects.zortex" (copied from the browser), as a
// path from the notes folder ("z/scan.pdf", "z/books", "projects.zortex");
// "" for anything else. As Neovim's link.site_path.
func SitePath(def string) string {
	def = strings.TrimSpace(def)
	for _, p := range []string{"/raw/", "/f/", "/n/"} {
		if strings.HasPrefix(def, p) {
			rest := def[len(p):]
			if i := strings.IndexAny(rest, "?#"); i >= 0 {
				rest = rest[:i]
			}
			if u, err := url.PathUnescape(rest); err == nil {
				rest = u
			}
			return strings.Trim(rest, "/")
		}
	}
	return ""
}

// IsParentRelative: "./" followed by a typed component ("./-Item",
// "./#Heading", "./:Label", "./*Bold", "./>Link") continues its parent
// line's link (Absolute); other "./" links are file paths.
func IsParentRelative(def string) bool {
	d := syntax.Trim(def)
	return len(d) > 2 && d[0] == '.' && d[1] == '/' && strings.IndexByte("#:-*>", d[2]) >= 0
}

func indentOf(line string) int {
	n := 0
	for n < len(line) && (line[n] == ' ' || line[n] == '\t') {
		n++
	}
	return n
}

// LinksOn: the plain links ([...], not ![...]) on a line, in order.
func LinksOn(line string) []*syntax.Span {
	var out []*syntax.Span
	syntax.Walk(syntax.Inline(line, 0, len(line)), func(sp *syntax.Span) {
		if sp.Type == "link" {
			out = append(out, sp)
		}
	})
	return out
}

// Absolute is the link a parent-relative link stands for: the first link of
// the nearest parent line (less indented, above line lnum) that has one,
// followed by the components after "./". Other links come back unchanged.
// core/link.absolute in the plugin is the same.
func Absolute(lines []string, lnum int, def string) (string, error) {
	d := syntax.Trim(def)
	if !IsParentRelative(d) {
		return d, nil
	}
	rest := d[2:]
	if lnum < 1 || lnum > len(lines) {
		return "", errors.New(NoParentLink)
	}
	want := indentOf(lines[lnum-1])
	for l := lnum - 1; l >= 1; l-- {
		text := lines[l-1]
		if strings.TrimSpace(text) == "" || indentOf(text) >= want {
			continue
		}
		for _, sp := range LinksOn(text) {
			parent := sp.Definition
			if IsParentRelative(parent) {
				abs, err := Absolute(lines, l, parent)
				if err != nil {
					return "", err
				}
				return abs + "/" + rest, nil
			}
			if !strings.HasPrefix(parent, "./") && !strings.HasPrefix(parent, "../") && !strings.HasPrefix(parent, "~") {
				return parent + "/" + rest, nil
			}
		}
		want = indentOf(text)
		if want == 0 {
			break
		}
	}
	return "", errors.New(NoParentLink)
}

type candidate struct {
	rel        string
	doc        *notes.Document
	start, end int
}

func mentionsArchive(d Definition) bool {
	for _, c := range d.Components {
		if c.Type == "tag" && syntax.Lower(c.Text) == syntax.Lower(notes.ArchiveTag) {
			return true
		}
	}
	return false
}

// Resolve returns every location a link resolves to, canonical first.
func Resolve(ix *notes.Index, link string, opts Options) ([]Result, error) {
	res, err := resolveIn(ix, link, opts)
	if len(res) > 0 || opts.IncludeArchived != nil {
		return res, err
	}
	// nothing in the live notes: the archives ([P/-Task] for a task archived
	// into z/archive.projects.zortex, which keeps the note's names)
	yes := true
	opts.IncludeArchived = &yes
	if more, err2 := resolveIn(ix, link, opts); err2 == nil && len(more) > 0 {
		return more, nil
	}
	return res, err
}

// resolveIn is Resolve over the live notes, or the archives too
// (opts.IncludeArchived, or a component is @Archive).
func resolveIn(ix *notes.Index, link string, opts Options) ([]Result, error) {
	if t := syntax.Trim(link); strings.HasPrefix(t, "@[") && strings.HasSuffix(t, "]") {
		return TagSearch(ix, t[2:len(t)-1], opts)
	}
	if t := strings.TrimSuffix(strings.TrimPrefix(syntax.Trim(link), "["), "]"); IsParentRelative(t) {
		var lines []string
		if opts.From != nil {
			lines = opts.From.Lines
		}
		abs, err := Absolute(lines, opts.Lnum, t)
		if err != nil {
			return nil, err
		}
		link = "[" + abs + "]"
	}
	def := Parse(link)
	if len(def.Components) == 0 {
		return nil, errors.New("Invalid link")
	}

	var cands []candidate
	var cat *notes.Catalog
	include := false
	// whole: cands is still every (included) note, so header components can
	// use the catalog's lookups instead of checking each note
	whole := false
	if def.Local {
		if opts.From == nil {
			return nil, errors.New("No buffer to resolve a local link in")
		}
		cands = []candidate{{rel: opts.From.Rel, doc: opts.From}}
	} else {
		include = mentionsArchive(def)
		if opts.IncludeArchived != nil {
			include = *opts.IncludeArchived
		}
		cat = ix.Catalog()
		whole = true // cands is built from the catalog only if needed
	}
	included := func(rels []string) []candidate {
		var out []candidate
		for _, rel := range rels {
			if include || !cat.IsArchived(rel) {
				if d := ix.Doc(rel); d != nil {
					out = append(out, candidate{rel: rel, doc: d})
				}
			}
		}
		return out
	}
	load := func(c *candidate) *notes.Document {
		if c.doc == nil {
			c.doc = ix.Doc(c.rel)
		}
		return c.doc
	}

	var results []Result
	for i, comp := range def.Components {
		last := i == len(def.Components)-1
		if comp.Type == "follow" && !last {
			return nil, errors.New("Nothing can come after " + comp.Original)
		}

		// Header components on every note: straight from the catalog
		if whole && (comp.Type == "article" || comp.Type == "tag") {
			var kept []candidate
			// notes, then documents (a note wins a name): named first, then tagged
			named := append(append([]string(nil), cat.WithName(comp.Text)...), cat.DocumentsWithName(comp.Text)...)
			tagged := append(append([]string(nil), cat.WithTag(comp.Text)...), cat.DocumentsWithTag(comp.Text)...)
			if comp.Type == "article" {
				kept = included(named)
				seen := map[string]bool{}
				for _, c := range kept {
					seen[c.rel] = true
				}
				for _, c := range included(tagged) {
					if !seen[c.rel] {
						kept = append(kept, c)
					}
				}
				if len(kept) == 0 {
					return nil, errors.New("No article found: " + comp.Text)
				}
			} else {
				kept = included(tagged)
			}
			if len(kept) > 0 {
				whole = false
				cands = kept
				if last {
					for _, c := range cands {
						lnum := c.doc.Header().NameLnum
						if lnum == 0 {
							lnum = 1
						}
						results = append(results, Result{Doc: c.doc, Lnum: lnum, Col: 1, Component: comp, Whole: true})
					}
				}
				continue
			}
			// a tag no note carries: a line search for "@tag" (below)
		}
		if whole {
			files := append(append([]string(nil), cat.Files(include)...), cat.Documents()...)
			cands = make([]candidate, len(files))
			for k, rel := range files {
				cands[k] = candidate{rel: rel}
			}
			whole = false
		}

		// Article and header-tag components select whole files
		var selectFile func(h syntax.Header) bool
		var rankFirst func(h syntax.Header) bool
		if !def.Local && comp.Type == "article" {
			selectFile = func(h syntax.Header) bool {
				return syntax.ListHas(h.Names, comp.Text) || syntax.ListHas(h.Tags, comp.Text)
			}
			rankFirst = func(h syntax.Header) bool { return syntax.ListHas(h.Names, comp.Text) }
		} else if !def.Local && comp.Type == "tag" {
			hasTag := func(h syntax.Header) bool { return syntax.ListHas(h.Tags, comp.Text) }
			for k := range cands {
				if d := load(&cands[k]); d != nil && hasTag(d.Header()) {
					selectFile = hasTag
					break
				}
			}
		}

		if selectFile != nil {
			var first, second []candidate
			for k := range cands {
				d := load(&cands[k])
				if d == nil || !selectFile(d.Header()) {
					continue
				}
				c := candidate{rel: cands[k].rel, doc: d}
				if rankFirst == nil || rankFirst(d.Header()) {
					first = append(first, c)
				} else {
					second = append(second, c)
				}
			}
			kept := append(first, second...)
			if len(kept) == 0 {
				if comp.Type == "article" {
					return nil, errors.New("No article found: " + comp.Text)
				}
				return nil, errors.New("No notes tagged @" + comp.Text)
			}
			cands = kept
			if last {
				for _, c := range cands {
					lnum := c.doc.Header().NameLnum
					if lnum == 0 {
						lnum = 1
					}
					results = append(results, Result{Doc: c.doc, Lnum: lnum, Col: 1, Component: comp, Whole: true})
				}
			}
			continue
		}

		var next []candidate
		for k := range cands {
			d := load(&cands[k])
			if d == nil {
				continue
			}
			matches := SearchLines(d.Lines, comp, cands[k].start, cands[k].end)
			if last {
				for _, m := range matches {
					results = append(results, Result{Doc: d, Lnum: m.Lnum, Col: m.Col, Component: comp, Link: m.Link, End: SectionEnd(d, m.Lnum, comp)})
				}
			} else if len(matches) > 0 {
				lnum := matches[0].Lnum
				next = append(next, candidate{rel: cands[k].rel, doc: d, start: lnum, end: SectionEnd(d, lnum, comp)})
			}
		}
		if !last {
			if len(next) == 0 {
				return nil, errors.New("No matches found for: " + comp.Original)
			}
			cands = next
		}
	}
	if len(results) == 0 {
		return nil, errors.New("No matches found for: " + def.Components[len(def.Components)-1].Original)
	}
	return results, nil
}

// ResolveFirst returns the canonical target of a link.
func ResolveFirst(ix *notes.Index, link string, opts Options) (*Result, error) {
	rs, err := Resolve(ix, link, opts)
	if err != nil {
		return nil, err
	}
	return &rs[0], nil
}
